 step("put policy transition to unknown state", "PUT", I + "/policies/compat-bad4", {"policy": {"description": "d", "default_state": "hot", "states": [{"name": "hot", "actions": [], "transitions": [{"state_name": "nope", "conditions": {"min_index_age": "1d"}}]}]}}),
 step("put policy duplicate state names", "PUT", I + "/policies/compat-bad5", {"policy": {"description": "d", "default_state": "hot", "states": [{"name": "hot", "actions": [], "transitions": []}, {"name": "hot", "actions": [], "transitions": []}]}}),
 step("put policy unknown action", "PUT", I + "/policies/compat-bad6", {"policy": {"description": "d", "default_state": "hot", "states": [{"name": "hot", "actions": [{"nope": {}}], "transitions": []}]}}),
 step("put policy bad condition", "PUT", I + "/policies/compat-bad7", {"policy": {"description": "d", "default_state": "hot", "states": [{"name": "hot", "actions": [], "transitions": [{"state_name": "hot", "conditions": {"min_index_age": "soon"}}]}]}}),
 step("put policy no body", "PUT", I + "/policies/compat-bad8"),
 step("put policy every action", "PUT", I + "/policies/compat-all", {"policy": {"description": "d", "default_state": "a", "states": [
    {"name": "a", "actions": [{"replica_count": {"number_of_replicas": 1}}, {"force_merge": {"max_num_segments": 1}}, {"read_only": {}}, {"read_write": {}}, {"index_priority": {"priority": 5}}, {"close": {}}, {"open": {}}, {"allocation": {"require": {"box": "hot"}, "wait_for": True}}, {"rollover": {"min_doc_count": 5}}, {"shrink": {"num_new_shards": 1, "force_unsafe": True}}, {"snapshot": {"repository": "r", "snapshot": "s"}}, {"notification": {"destination": {"custom_webhook": {"url": "http://127.0.0.1:18080/200"}}, "message_template": {"source": "x"}}}, {"retry": {"count": 2, "backoff": "constant", "delay": "1m"}, "read_only": {}}], "transitions": [{"state_name": "b", "conditions": {"cron": {"cron": {"expression": "* * * * *", "timezone": "UTC"}}}}, {"state_name": "b", "conditions": {"min_doc_count": 1}}, {"state_name": "b", "conditions": {"min_size": "1gb"}}]},
    {"name": "b", "actions": [{"alias": {"actions": [{"add": {"aliases": ["compat-ism-al"]}}]}}, {"timeout": "1h", "delete": {}}], "transitions": []}], "ism_template": [{"index_patterns": ["compat-ism-tpl-*"], "priority": 10}]}}),
 step("get every action policy", "GET", I + "/policies/compat-all"),
